  constructor(props) {
    super(props);

    this.state = {
      notifications_: [],

      // Setpoints
      variables: [],
      variables_: [],
      alarms_: [],

      // Events
      files: [],
      eventChart: false,

      chartEmitter: new ChartEmitter(),
    };

    let self = this;

    this.state.chartEmitter.on(constants.EVENT_VARIABLES, (variables, setpoints) => {
      self.setState({ variables_: variables, variables: setpoints }, () => {
        $(`#setpoint-main-chart`).modal('open');
      });
    });

    this.state.chartEmitter.on(constants.EVENT_OPEN_EVENT_CHART, (id) => {
      self.getEventChart(id);
    });   

    this.state.chartEmitter.on(constants.EVENT_OPEN_CREATE_EVENT_CHART, (json) => {
      let keyInputVariableEvent = `#input-variable-event-main-chart`;
      let keyInputCreatedAtEvent = `#input-created-at-event-main-chart`;

      let inputVariable = document.querySelector(keyInputVariableEvent);
      let inputCreatedAt = document.querySelector(keyInputCreatedAtEvent);

      inputVariable.value = json.variable_name;
      inputCreatedAt.value = json.created_at_in;

      self.setState({ eventChart: json }, () => {
        $(`#events-main-chart`).modal('open');
      });
    });
  }

